242	function canonicalStringify(value: unknown): string {
243	  if (value === null || typeof value !== "object") return JSON.stringify(value);
244	  if (Array.isArray(value)) return `[${value.map(canonicalStringify).join(",")}]`;
245	  const obj = value as Record<string, unknown>;
246	  const keys = Object.keys(obj).sort();
247	  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalStringify(obj[k])}`).join(",")}}`;
