mit, and a person waits at most half
53	 * a minute plus however long the agent's current tool call takes -- which is usually
54	 * the larger half.
55	 */
56	const DEFAULT_INTERVAL_SECONDS = 30;
57	
58	export interface StopComment {
59	  body?: string;
60	  created_at?: string;
61	}
62	
63	/**
64	 * Whether any of these comments is a stop request belonging to this run.
65	 *
66	 * Exported for its test: the cutoff is the part that is easy to get subtly wrong, and
67	 * getting it wrong in the permissive direction means an issue that can never be
68	 * worked on again.
69	 */
70	export function stopRequested(comments: StopComment[], since: Date): boolean {
71	  return comments.some((c) => {
72	    if (!STOP_TAG.has(c.body ?? "")) return false;
73	    const at = c.created_at ? Date.parse(c.created_at) : NaN;
74	    // An unparseable timestamp is not a reason to ignore a stop somebody asked for.
75	    // The failure it risks -- stopping one run early -- is recoverable by a comment;
76	    // the other direction is a run nobody can interrupt.
77	    return Number.isNaN(at) || at > since.getTime();
78	  });
79	}
80	
81	function poll(repo: string, number: string, since: Date): boolean {
82	  const { code, stdout } = gh(
83	    "api", `repos/${repo}/issues/${number}/comments`,
84	    "--method", "GET",
85	    "-f", `since=${since.toISOString()}`,
86	    "--jq", "[.[] | {body, created_at}]",
87	  );
88	  if (code !== 0) return false;
89	  try {
90	    return stopRequested(JSON.parse(stdout || "[]") as StopComment[], since);
91	  } catch {
92	    return false;
93	  }
94	}
95	
96	async function main(): Promise<void> {
97	  const { values } = parseArgs({
98	    args: Bun.argv.slice(2),
99	    options: {
100	      number: { type: "string" },
101	      "stop-file": { type: "string" },
102	      since: { type: "string" },
103	      "interval-seconds": { type: "string" },
104	    },
105	  });
106	
107	  if (!values.number || !values["stop-file"] || !values.since) {
108	    console.error("usage: watch_for_stop.ts --number N --stop-file PATH --since ISO8601");
109	    process.exit(2);
110	  }
111	
112	  const repo = process.env.GITHUB_REPOSITORY ?? "";
113	  const since = new Date(values.since);
114	  const intervalMs = (Number(values["interval-seconds"]) || DEFAULT_INTERVAL_SECONDS) * 1000;
115	
116	  console.error(`Watching #${values.number} for a stop request since ${since.toISOString()}`);
117	
118	  for (;;) {
119	    await Bun.sleep(intervalMs);
120	    if (!poll(repo, String(values.number), since)) continue;
121	    // Content, not an empty file: a person reading the run's directory afterwards
122	    // should find out why the run stopped without having to know what the path means.
123	    writeFileSync(values["stop-file"], `stop requested on #${values.number}\n`);
124	    console.error(`Stop request found; wrote ${values["stop-file"]}`);
125	    return;
126	  }
127	}
